    'REGULATOR NAME': /(?:regulator|REGULATOR)\s*[:=]\s*['"`]|FW_REGULATOR|Sector regulator/,
    'JURISDICTION NEXUS (established_in)': /established_in\s*[:=]|estab\s*:\s*\//,
