+'use strict';
+/**
+ * A BUILD THAT RETURNS AN OBJECT IS NOT AN AUDIT.
+ *
+ * The queue reported 1,034 audits 'done'. audit_pages held SEVENTEEN ROWS. 1,004 "done" audits had NO PAGE, and
